effect.shader:
const int N = 7;
const float OFF[7] = float[7](-3.0,-2.0,-1.0,0.0,1.0,2.0,3.0);
const float WT[7]  = float[7](0.071,0.131,0.190,0.216,0.190,0.131,0.071);

float hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }

void main() {
    vec2 d = (acPass == 0) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec2 passo = d * acTexelSize * (radius * acEscalaDePixel);
    vec4 soma = vec4(0.0);
    for (int i = 0; i < N; i++) {
        vec2 uv = acScreenNorm + passo * OFF[i];
        soma += ((acPass == 0) ? texture(inputImg, uv) : texture(hblur, uv)) * WT[i];
    }
    if (acPass == 0) { fragColor = soma; return; }

    float g = (hash(acScreenNorm * 1024.0 + vec2(acTime * speed * 37.0)) - 0.5) * 2.0 * grain;
    fragColor = vec4(soma.rgb + g, soma.a);
}
